mapper.sql:
price BETWEEN #{priceMin} AND #{priceMax}
AND weight_g IS NOT NULL AND weight_g < #{weightMax}
AND listing_days IS NOT NULL AND listing_days < #{listingDaysMax}
AND (
    (listing_days <= 30 AND units IS NOT NULL AND units >= #{sales30})
    OR (listing_days <= 60 AND units IS NOT NULL AND units >= #{sales60})
    OR (listing_days <= 90 AND units IS NOT NULL AND units >= #{sales90})

        OR (bsr IS NOT NULL AND bsr > 0 AND bsr < #{bsrMax})

)

1 = 1
AND price >= #{q.priceMin}
AND price <= #{q.priceMax}
AND units >= #{q.unitsMin}
AND units <= #{q.unitsMax}
AND listing_days >= #{q.listingDaysMin}
AND listing_days <= #{q.listingDaysMax}
AND bsr <= #{q.bsrMax}
AND weight_g IS NOT NULL AND weight_g <= #{q.weightMax}
AND variations <= #{q.maxVariantCount}

    AND UPPER(fulfillment) IN
    #{method}


    AND (

        node_label_path LIKE CONCAT('%', #{category}, '%')

    )


    AND ()

mapper.select:
WITH watchlist_ranked AS ( SELECT sw.*, ROW_NUMBER() OVER ( PARTITION BY sw.marketplace, sw.seller_name ORDER BY sw.updated_at DESC, sw.id DESC ) AS rn FROM shop_watchlist sw WHERE sw.marketplace = #{q.marketplace} AND LOWER(TRIM(sw.seller_name)) != 'amazon' AND sw.status = #{q.watchlistStatus} AND sw.source_type = #{q.sourceType}
AND sw.seller_name IN #{seller}
AND sw.seller_name LIKE CONCAT('%', #{q.sellerKeyword}, '%')
), watchlist_latest AS ( SELECT * FROM watchlist_ranked WHERE rn = 1 ), ranked_products AS ( SELECT ds.*, COALESCE(NULLIF(ds.parent_asin, ''), ds.asin) AS product_key, CASE WHEN ds.units IS NULL THEN 'UNKNOWN' WHEN ds.units >= 100 THEN 'A' WHEN ds.units >= 50 THEN 'B' WHEN ds.units >= 15 THEN 'C' ELSE 'D' END AS sales_tier_calc, COALESCE(NULLIF(TRIM(SUBSTRING_INDEX(ds.node_label_path, ':', -1)), ''), 'UNKNOWN') AS category_leaf, ROW_NUMBER() OVER ( PARTITION BY ds.marketplace, ds.seller_name, COALESCE(NULLIF(ds.parent_asin, ''), ds.asin) ORDER BY ds.batch_code DESC, ds.updated_at DESC, ds.id DESC ) AS rn FROM shop_products ds WHERE ds.marketplace = #{q.marketplace} AND ds.seller_name IS NOT NULL AND ds.seller_name != '' AND LOWER(TRIM(ds.seller_name)) != 'amazon' AND ds.asin IS NOT NULL AND ds.asin != ''
AND ds.batch_code IN #{batch}
AND ds.seller_name IN #{seller}
AND ds.seller_name LIKE CONCAT('%', #{q.sellerKeyword}, '%')
), base AS ( SELECT * FROM ranked_products WHERE rn = 1 ), enriched AS ( SELECT base.*, CASE WHEN THEN 1 ELSE 0 END AS pass_hit, CASE WHEN THEN 1 ELSE 0 END AS m01_hit FROM base ), shop_agg AS ( SELECT marketplace, seller_name AS sellerName, MAX(seller_id) AS sellerId, COUNT(*) AS productCount, SUM(pass_hit) AS passedProductCount, SUM(m01_hit) AS m01HitCount, ROUND(SUM(m01_hit) / NULLIF(COUNT(*), 0), 4) AS m01HitRatio, ROUND(AVG(listing_days), 2) AS avgListingDays, ROUND(AVG(units), 2) AS avgUnits, SUM(CASE WHEN listing_days IS NOT NULL AND listing_days <= 30 THEN 1 ELSE 0 END) AS new30Count, SUM(CASE WHEN listing_days IS NOT NULL AND listing_days <= 90 THEN 1 ELSE 0 END) AS new90Count, SUM(CASE WHEN sales_tier_calc = 'A' THEN 1 ELSE 0 END) AS aCount, SUM(CASE WHEN sales_tier_calc = 'B' THEN 1 ELSE 0 END) AS bCount, SUM(CASE WHEN sales_tier_calc = 'C' THEN 1 ELSE 0 END) AS cCount, SUM(CASE WHEN sales_tier_calc = 'D' THEN 1 ELSE 0 END) AS dCount, SUM(CASE WHEN sales_tier_calc IN ('A','B','C') THEN 1 ELSE 0 END) AS abcCount, ROUND(SUM(CASE WHEN sales_tier_calc IN ('A','B','C') THEN 1 ELSE 0 END) / NULLIF(COUNT(*), 0), 4) AS abcRatio, SUBSTRING_INDEX(GROUP_CONCAT(CASE WHEN pass_hit = 1 THEN category_leaf END ORDER BY units DESC SEPARATOR '||'), '||', 1) AS topCategory, MAX(batch_code) AS latestBatchCode FROM enriched GROUP BY marketplace, seller_name ), candidates AS (
SELECT wl.marketplace, wl.seller_name AS sellerName, COALESCE(sa.sellerId, wl.seller_id) AS sellerId, COALESCE(sa.productCount, 0) AS productCount, COALESCE(sa.passedProductCount, 0) AS passedProductCount, COALESCE(sa.m01HitCount, 0) AS m01HitCount, COALESCE(sa.m01HitRatio, 0) AS m01HitRatio, sa.avgListingDays, sa.avgUnits, COALESCE(sa.new30Count, 0) AS new30Count, COALESCE(sa.new90Count, 0) AS new90Count, COALESCE(sa.aCount, 0) AS aCount, COALESCE(sa.bCount, 0) AS bCount, COALESCE(sa.cCount, 0) AS cCount, COALESCE(sa.dCount, 0) AS dCount, COALESCE(sa.abcCount, 0) AS abcCount, COALESCE(sa.abcRatio, 0) AS abcRatio, sa.topCategory, sa.latestBatchCode, wl.id AS watchlistId, wl.status AS watchlistStatus, wl.source_type AS sourceType, wl.source_code AS sourceCode, wl.reason, wl.hit_count AS sourceHitCount FROM watchlist_latest wl LEFT JOIN shop_agg sa ON sa.marketplace COLLATE utf8mb4_unicode_ci = wl.marketplace AND sa.sellerName COLLATE utf8mb4_unicode_ci = wl.seller_name
SELECT sa.*, wl.id AS watchlistId, wl.status AS watchlistStatus, wl.source_type AS sourceType, wl.source_code AS sourceCode, wl.reason, wl.hit_count AS sourceHitCount FROM shop_agg sa LEFT JOIN watchlist_latest wl ON wl.marketplace = sa.marketplace COLLATE utf8mb4_unicode_ci AND wl.seller_name = sa.sellerName COLLATE utf8mb4_unicode_ci
), filtered AS ( SELECT * FROM candidates WHERE 1 = 1 AND passedProductCount > 0 AND productCount >= #{q.minProductCount} AND passedProductCount >= #{q.minPassedProductCount} AND m01HitCount >= #{q.minM01HitCount} AND avgListingDays <= #{q.avgListingDaysMax} ) SELECT filtered.*, COUNT(*) OVER() AS totalRows, SUM(productCount) OVER() AS totalProductCount, SUM(passedProductCount) OVER() AS totalPassedProductCount, SUM(m01HitCount) OVER() AS totalM01HitCount FROM filtered ORDER BY
productCount m01HitCount avgListingDays new90Count passedProductCount
ASCDESC, sellerName ASC LIMIT #{q.offset}, #{q.size}
